#define SCB (&scb_regs)
#define SysTick_CTRL_ENABLE_Msk 1U
#define SysTick_CTRL_TICKINT_Msk 2U
#define SysTick_CTRL_CLKSOURCE_Msk 4U
#define SCB_ICSR_PENDSTSET_Msk 0x04000000U
static inline uint32_t __get_PRIMASK(void) { return mask; }
